mapper.select:
SELECT 
FROM WORK_READING_RECORD
WHERE WORK_USER_NO = #{owner}
AND REREAD = #{reread}
AND LOCATE(LOWER(#{title}), LOWER(TITLE)) > 0
AND LOCATE(LOWER(#{author}), LOWER(AUTHOR)) > 0
AND (STARTED_ON IS NOT NULL OR COMPLETED_ON IS NOT NULL)
AND (COMPLETED_ON IS NULL OR COMPLETED_ON >= #{from})
AND COALESCE(STARTED_ON, COMPLETED_ON) <= #{to}
ORDER BY ID DESC

mapper.update:
UPDATE WORK_READING_RECORD
SET TITLE = #{record.title}, AUTHOR = #{record.author},
	TRANSLATOR = #{record.translator,jdbcType=VARCHAR}, STARTED_ON = #{record.startedOn,jdbcType=DATE},
	COMPLETED_ON = #{record.completedOn,jdbcType=DATE}, CONTENT = #{record.content,jdbcType=VARCHAR},
	RATING = #{record.rating,jdbcType=DECIMAL}, NOTES = #{record.notes,jdbcType=VARCHAR}
	, READING_ROUND = #{record.readingRound}
	, REREAD = #{record.reread}
WHERE WORK_USER_NO = #{owner} AND ID = #{id}
